            testChildProperty<IfActionUsageMeta>({
                proto: IfActionUsageMeta,
                edgeProto: ParameterMembershipMeta,
                targetProto: target,
                property: prop,
            });
        });
    });

    describe(`${SatisfyRequirementUsage} elements`, () => {
