export class StringLengthFunction extends BuiltinFunction {
    override call(
        expression: InvocationExpressionMeta,
        target: ElementMeta,
        evaluator: ModelLevelExpressionEvaluator
    ): ExpressionResult {
        const str = evaluator.asString(expression, 0, target);
        return [str.length];
    }
}

