describe("succession actions", () => {
    const expectPrintedAs = (
        text: string,
        options: DeepPartial<Omit<PrinterTestContext, "lang" | "node">> = {}
    ): jest.JestMatchers<Promise<string>> => {
        return expectPrinted(text, {
            lang: "sysml",
            node: Namespace,
            ...options,
        });
    };

    it("should print empty succession usage", () => {
        return expectPrintedAs(
            "part def P  { then    [ * ]    occurrence O : A {} }"
        ).resolves.toEqual(
            `part def P {
    then [*] occurrence O : A {}
}\n`
        );
    });
    it("should print action nodes", () => {
        return expectPrintedAs(
            `
        action a1 {
            first start;
            then    send    S()   via A     to b;
            then    accept     when    b.f;
            then    decide;
                if true
                    then m;
                else done;
        }`
        ).resolves.toEqual(
            `action a1 {
    first start;
    then send S() via A to b;
    then accept when b.f;
    then decide;
        if true then m;
        else done;
}\n`
        );
    });

    it("should print simple succession", () => {
        return expectPrintedAs(
            `
        action def ControlNodeTest {
            action   A1;
            then   J;


            then B1;
        }`
        ).resolves.toEqual(
            `action def ControlNodeTest {
    action A1;
    then J;

    then B1;
}\n`
        );
    });

    it("should print succession to action body", () => {
        return expectPrintedAs(
            `
            action def TakePicture {
                in item scene : Scene;
                out item picture : Picture;

                action focus : Focus {
                    in item scene = TakePicture::scene;
                    out item image;
                }

                flow from focus.image to shoot.image;

                then action shoot : Shoot {
                    in item;
                    out item picture = TakePicture::picture;
                }
            }`
        ).resolves.toEqual(
            `action def TakePicture {
    in item scene : Scene;
    out item picture : Picture;

    action focus : Focus {
        in item scene = TakePicture::scene;
        out item image;
    }

    flow from focus.image to shoot.image;

    then action shoot : Shoot {
        in item;
        out item picture = TakePicture::picture;
    }
}\n`
        );
    });

    it("should print transition usage", () => {
        return expectPrintedAs(
            `
                action A {
            first focus 
                if focus.image.isWellFocused then shoot;
                }`
        ).resolves.toEqual(
            `action A {
    first focus if focus.image.isWellFocused then shoot;
}\n`
        );
    });

    it("shouldprint forked successions", () => {
        return expectPrintedAs(
            `
            action def Brake {
                action TurnOn;

                then fork;
                    then monitorBrakePedal;
                    then monitorTraction;
                    then braking;
                    then action A;

                action monitorBrakePedal : MonitorBrakePedal;
                then joinNode;

                action monitorTraction : MonitorTraction;
                then joinNode;

                action braking : Braking;
                then joinNode;

                join joinNode;
                then done;
            }`
        ).resolves.toEqual(
            `action def Brake {
    action TurnOn;

    then fork;
        then monitorBrakePedal;
        then monitorTraction;
        then braking;
        then action A;

    action monitorBrakePedal : MonitorBrakePedal;
    then joinNode;

    action monitorTraction : MonitorTraction;
    then joinNode;

    action braking : Braking;
    then joinNode;

    join joinNode;
    then done;
}\n`
        );
    });

    it("should print decision transitions", () => {
        return expectPrintedAs(
            `
            action a1 {
                first start;
                then decide;
                if true
                    then m;
                    else done;
                then action a;
            }`
        ).resolves.toEqual(
            `action a1 {
    first start;
    then decide;
        if true then m;
        else done;
    then action a;
}\n`
        );
    });

    it("should print nested decision transitions", () => {
        return expectPrintedAs(
            `
            action a1 {
                first start;
                then decide;
                then decide;
                    if true
                        then m;
                        else done;
                then done;
                first x then b;
            }`
        ).resolves.toEqual(
            `action a1 {
    first start;
    then decide;
        then decide;
            if true then m;
            else done;
        then done;
    first x then b;
}\n`
        );
    });

    it("should not indent successions after merge and join nodes", () => {
        return expectPrintedAs(
            `
            action a1 {
                first start;
                then join;
                then merge;
                then done;
            }`
        ).resolves.toEqual(
            `action a1 {
    first start;
    then join;
    then merge;
    then done;
}\n`
        );
    });
});

