        node,
        context,
        {
            binding: keyword("to"),
            format: context.format.binary_allocation_usages,
            naryPrefix: keyword("allocate"),
            source: {
                keyword: "allocate",
                format: SourceFormatAlways,
            },
            printer: printConnectorEndMember,
        }
    );
}

