import { getName } from "../../model/naming";

export class SysMLNameProvider extends DefaultNameProvider {
    // overriding name provider methods since names can also be provided by the
    // short name

    override getName(node: AstNode): string | undefined {
        if (isElement(node)) {
            return getName(node.$meta);
        }
        return undefined;
    }

    override getNameNode(node: AstNode): CstNode | undefined {
        return (
            findNodeForProperty(node.$cstNode, "declaredName") ??
            findNodeForProperty(node.$cstNode, "declaredShortName")
        );
    }
}

