        ConfigurationProvider: SysMLConfigurationProvider;
        IndexManager: SysMLIndexManager;
        DocumentBuilder: SysMLDocumentBuilder;
        FileSystemProvider: SysMLFileSystemProvider;
        LangiumDocuments: SysMLDocuments;
