        private namespace B3;
    }
}
`;

const N4 = `
namespace N4 {
    public import N1::N2::B;

    namespace C;
}
`;

const N5 = `namespace N5 {
    public import N1::N2::*;

    namespace C;
}
`;

const N6 = `namespace N6 {
    public import N1::**;

    namespace C;
}
`;

