    expect(childrenNames(namespace.children[1].target as Namespace)).toEqual([
        "N6::C",
        "N1",
        "N1::A",
        "N1::N2",
        "N1::N2::B",
    ]);
});

test("recursive namespace imports import namespaces recursively excluding the referenced namespace", async () => {
