import {
    printDoc,
    group,
    hardline,
    align,
    text,
    line,
    breakParent,
    DefaultPrinterConfig,
    conditionalGroup,
    PrinterConfig,
    Doc,
    fill,
    join,
    dedent,
    indent,
    trim,
    softline,
    literalline,
    ifBreak,
