                    text("function", { type: ls.SemanticTokenTypes.keyword }),
                    line,
                    text("hello", {
                        type: ls.SemanticTokenTypes.function,
                        modifiers: [ls.SemanticTokenModifiers.deprecated],
                    }),
                    text(" "),
                    text("("),
                    softline,
                    text(")"),
                ]),

                { ...DefaultPrinterConfig, highlighting: true }
            )
        ).toMatchInlineSnapshot(`
{
  "cursors": [],
  "highlighting": [
    {
      "end": 8,
      "modifiers": undefined,
      "start": 0,
      "type": "keyword",
    },
    {
      "end": 14,
      "modifiers": [
        "deprecated",
      ],
      "start": 9,
      "type": "function",
    },
  ],
  "text": "function hello ()
",
}
`);
    });
});

describe("prettier conformance", () => {
    it("should break groups like prettier", () => {
        // https://prettier.io/playground/#N4Igxg9gdgLgprEAuc0DOMAEBDTBeTACmwEolMAVfAPkwEYAGJkAGhAgAcYBLdZUbACdBEAO4AFIQjTIQ2ADajsATxlsARoOxgA1nBgBlbAFs4AGW5Q4yAGYK0cDVt36DHbZYDmyGIICujiAOxtw+-
        const doc = [
            group([
                text("const"),
                text(" "),
                group([
                    group(text("a")),
                    text(" ="),
                    group(indent(line), { id: "assignment" }),
                    lineSuffixBoundary,
                    indentIfBreak(
                        group([
                            group(
                                group([
                                    text("("),
                                    indent([softline, text("a")]),
                                    ifBreak(text(","), literals.emptytext),
                                    softline,
                                    text(")"),
                                    text(":"),
                                    text(" "),
                                    text("T"),
                                ]),
                                { id: "arrow-chain" }
                            ),
                            text(" =>"),
                            group(indent([line, text("1000")])),
